    for row in grid:
        for val in row:
            freq[val] += 1

    background = freq.most_common(1)[0][0]

    # Target selection: number of distinct rows/cols (spreadiness)
    def spreadiness(color):
        positions = []
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] == color:
                    positions.append((r, c))
        if len(positions) <= 1:
            return 0
        row_set = set(p[0] for p in positions)
        col_set = set(p[1] for p in positions)
        return (len(row_set) - 1) * (len(col_set) - 1)

    non_bg = [c for c in freq if c != background]
    target = max(non_bg, key=spreadiness) if non_bg else 0

    positions = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == target]
