    cols = [p[1] for p in positions]
    rows_sorted = sorted(set(rows))
    cols_sorted = sorted(set(cols))
    rmin, rmax = rows_sorted[0], rows_sorted[-1]
    cmin, cmax = cols_sorted[0], cols_sorted[-1]

